#include <cstdio>
#include <algorithm>
using namespace std;

int mod;
inline int add_modulo(int x) {
    return x >= mod ? x - mod : x;
}
inline int subtract_modulo(int x) {
    return x < 0 ? x + mod : x;
}
int fast_power(int base, int exponent) {
    int result=1;
    while (exponent > 0) {
        if (exponent & 1) result = (long long)result * base % mod;
        base = (long long)base * base % mod;
        exponent >>= 1;
    }
    return result;
}
struct PairStruct {
    int first, second;
    PairStruct(int f=0, int s=0):first(f), second(s) {}
};
PairStruct operator+(const PairStruct &a, const PairStruct &b) {
    return PairStruct(add_modulo(a.first + b.first), add_modulo(a.second + b.second));
}
PairStruct operator*(const PairStruct &a, const PairStruct &b) {
    return PairStruct((long long)a.first * b.first % mod, add_modulo((long long)a.first * b.second % mod + (long long)a.second * b.first % mod));
}
int n, m, maxN=100000;
int factorials[100005], inv_factorials[100005], inv_numbers[100005];
PairStruct dp_array[1005], prefix_table[1005][1005];

int sum_series_final(int x) {
    return (long long)x * (x+1) / 2 % mod;
}

int main() {
    scanf("%d%d%d", &n, &m, &mod);
    factorials[0]=inv_factorials[0]=1;
    for (int i=1; i<=maxN; i++) {
        factorials[i] = (long long)i * factorials[i-1] % mod;
        inv_factorials[i] = fast_power(factorials[i], mod-2);
        inv_numbers[i] = fast_power(i, mod-2);
    }
    dp_array[0] = PairStruct(1,0);
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=i; j++) {
            PairStruct temp = dp_array[j-1] * dp_array[i-j];
            temp.second = add_modulo((long long)temp.second * (i+1) % mod + (long long)temp.first * add_modulo(sum_series_final(j-1) + sum_series_final(i-j)) % mod);
            temp.second = (long long)temp.second * inv_numbers[i] % mod;
            temp.first = (long long)temp.first * (i+1) % mod * inv_numbers[i] % mod;
            dp_array[i] = dp_array[i] + temp;
        }
    }
    prefix_table[0][0] = PairStruct(1,0);
    for (int i=1; i<=n; i++) {
        for (int j=0; j<=min(i,m); j++) {
            if (i==j) prefix_table[i][j]=dp_array[i];
            for (int k=0; k<j && k<i; k++) {
                prefix_table[i][j]=prefix_table[i][j]+dp_array[k]*prefix_table[i-k-1][j-k];
            }
        }
    }
    int answer_final= (long long)prefix_table[n][m].second*factorials[m]%mod;
    printf("%d\n", answer_final);
    return 0;
}
